package com.bryophytastaffhelper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import net.runelite.api.ChatMessageType;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Test;

public class BryophytaStaffHelperPluginTest
{
	@Test
	public void parsesChargeMessageFromGameChat()
	{
		assertEquals(Integer.valueOf(42), BryophytaStaffHelperPlugin.parseChargeCount("The nature staff has 42 charges."));
		assertEquals(Integer.valueOf(999), BryophytaStaffHelperPlugin.parseChargeCount("Your Bryophyta's staff has 999 charges."));
	}

	@Test
	public void parsesChargeMessageFromAnyChatType()
	{
		assertEquals(Integer.valueOf(42), BryophytaStaffHelperPlugin.parseChargeCount("The nature staff has 42 charges."));
		assertEquals(Integer.valueOf(7), BryophytaStaffHelperPlugin.parseChargeCount("Your Bryophyta's staff has 7 charges remaining."));
	}

	@Test
	public void keepsLowChargeWarningFromLooping()
	{
		assertEquals(Integer.valueOf(5), BryophytaStaffHelperPlugin.decrementCharge(6));
		assertEquals(Integer.valueOf(0), BryophytaStaffHelperPlugin.decrementCharge(0));
	}

	@Test
	public void savedRuneCountsWithoutReducingCharges()
	{
		assertEquals(5, BryophytaStaffHelperPlugin.incrementSavedRunes(4));
	}

	@Test
	public void ignoresStaleChargeCheckImmediatelyAfterNatureRuneCast()
	{
		assertTrue(BryophytaStaffHelperPlugin.shouldIgnoreChargeMessage(Integer.valueOf(2), true, 2));
		assertTrue(!BryophytaStaffHelperPlugin.shouldIgnoreChargeMessage(Integer.valueOf(3), true, 2));
	}

	@Test
	public void natureRuneSpellCostMatchesRuneUsage()
	{
		assertEquals(2, BryophytaStaffHelperPlugin.getNatureRuneCost("Bones to Bananas"));
		assertEquals(2, BryophytaStaffHelperPlugin.getNatureRuneCost("Bind"));
		assertEquals(1, BryophytaStaffHelperPlugin.getNatureRuneCost("Superheat Item"));
		assertEquals(4, BryophytaStaffHelperPlugin.getNatureRuneCost("Energy Transfer"));
		assertEquals(0, BryophytaStaffHelperPlugin.getNatureRuneCost("Fire Blast"));
	}

	@Test
	public void natureRuneSpellWhitelistMatchesRealSpellNames()
	{
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Bones to Bananas"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Bind"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Low Level Alchemy"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Enchant Crossbow Bolt (Emerald)"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Superheat Item"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Geomancy"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Entangle"));
		assertTrue(BryophytaStaffHelperPlugin.isNatureRuneSpell("Energy Transfer"));
		assertTrue(!BryophytaStaffHelperPlugin.isNatureRuneSpell("Fire Blast"));
	}

	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BryophytaStaffHelperPlugin.class);
		RuneLite.main(args);
	}
}

package com.bryophytastaffhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BryophytaStaffHelperConfig.GROUP)
public interface BryophytaStaffHelperConfig extends Config
{
	String GROUP = "bryophytastaffhelper";

	@ConfigItem(
		keyName = "lowChargeWarning",
		name = "Low charge warning",
		description = "Send a notification when the checked charge count is at or below this value."
	)
	@Range(max = 1_000)
	default int lowChargeWarning()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showInfobox",
		name = "Show charge infobox",
		description = "Show the last checked staff charge count in an infobox."
	)
	default boolean showInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyUncharged",
		name = "Warn when uncharged",
		description = "Notify when an uncharged Bryophyta's staff is equipped."
	)
	default boolean notifyUncharged()
	{
		return true;
	}
}

package com.bryophytastaffhelper;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.ItemID;
import net.runelite.api.ItemContainer;
import net.runelite.api.InventoryID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(
	name = "Bryophyta's Staff Helper",
	description = "Tracks Bryophyta's staff charges and warns before they run out.",
	tags = {"bryophyta", "staff", "charges", "nature", "runes", "magic"}
)
public class BryophytaStaffHelperPlugin extends Plugin
{
	static final int MAX_CHARGES = 1_000;
	private static final Pattern CHARGE_MESSAGE = Pattern.compile("(?i).*(?:bryophyta.?s|nature) staff.*?(?:has|have)?\\s*([\\d,]{1,5})\\s*charges?(?:\\s*(?:remaining|left))?.*");
	private static final String SAVED_NATURE_RUNE_MESSAGE = "your staff saved you a nature rune.";

	@Inject private Client client;
	@Inject private ItemManager itemManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private Notifier notifier;
	@Inject private ConfigManager configManager;
	@Inject private BryophytaStaffHelperConfig config;

	private BryophytaStaffInfoBox infoBox;
	private int charges = -1;
	private int savedRunes;
	private boolean lowChargeNotified;
	private boolean unchargedNotified;
	private boolean ignoreNextChargeMessage;
	private int lastChargeBeforeSpellCast = -1;
	private long lastNatureRuneCastTimeMs;
	private String lastNatureRuneCastKey;

	@Provides
	BryophytaStaffHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BryophytaStaffHelperConfig.class);
	}

	@Override
	protected void startUp()
	{
		refreshInfoBox();
	}

	@Override
	protected void shutDown()
	{
		removeInfoBox();
		charges = -1;
		savedRunes = 0;
		lowChargeNotified = false;
		unchargedNotified = false;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		String message = event.getMessage();
		if (message == null)
		{
			return;
		}

		Integer parsedCharges = parseChargeCount(message);
		if (parsedCharges != null)
		{
			if (shouldIgnoreChargeMessage(parsedCharges, ignoreNextChargeMessage, lastChargeBeforeSpellCast))
			{
				ignoreNextChargeMessage = false;
				lastChargeBeforeSpellCast = -1;
				return;
			}
			ignoreNextChargeMessage = false;
			lastChargeBeforeSpellCast = -1;
			setCharges(parsedCharges);
			return;
		}

		if (SAVED_NATURE_RUNE_MESSAGE.equalsIgnoreCase(message.trim()))
		{
			savedRunes = incrementSavedRunes(savedRunes);
			refreshInfoBox();
		}
	}

	static Integer parseChargeCount(String message)
	{
		Matcher matcher = CHARGE_MESSAGE.matcher(message);
		if (!matcher.matches())
		{
			return null;
		}
		return Integer.parseInt(matcher.group(1).replace(",", ""));
	}

	static Integer decrementCharge(int currentCharges)
	{
		return Math.max(0, currentCharges - 1);
	}

	static boolean shouldIgnoreChargeMessage(Integer parsedCharges, boolean ignoreNextChargeMessage, int lastChargeBeforeSpellCast)
	{
		return ignoreNextChargeMessage && parsedCharges != null && parsedCharges == lastChargeBeforeSpellCast;
	}

	static int incrementSavedRunes(int currentSavedRunes)
	{
		return currentSavedRunes + 1;
	}

	static int getNatureRuneCost(String spellName)
	{
		String natureSpellName = getNatureRuneSpellName(spellName);
		if (natureSpellName == null)
		{
			return 0;
		}

		switch (natureSpellName)
		{
			case "bones to bananas":
			case "bones to peaches":
				return 2;
			case "bind":
			case "snare":
			case "entangle":
				return 2;
			case "dark lure":
				return 3;
			case "energy transfer":
				return 4;
			default:
				return 1;
		}
	}

	static boolean isNatureRuneSpell(String spellName)
	{
		return getNatureRuneSpellName(spellName) != null;
	}

	static String getNatureRuneSpellName(String spellName)
	{
		if (spellName == null)
		{
			return null;
		}

		String normalized = spellName.trim().toLowerCase();
		String[] natureSpellNames = {
			"bones to bananas",
			"basic reanimation",
			"bind",
			"low level alchemy",
			"enchant crossbow bolt (emerald)",
			"adept reanimation",
			"superheat item",
			"snare",
			"dark lure",
			"high level alchemy",
			"bones to peaches",
			"geomancy",
			"harmony island teleport",
			"degrime",
			"expert reanimation",
			"ward of arceuus",
			"spin flax",
			"tan leather",
			"resurrect crows",
			"entangle",
			"fertile soil",
			"plank make",
			"master reanimation",
			"energy transfer"
		};

		for (String natureSpellName : natureSpellNames)
		{
			if (normalized.contains(natureSpellName))
			{
				return natureSpellName;
			}
		}

		return null;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event == null || !"Cast".equalsIgnoreCase(event.getMenuOption()))
		{
			return;
		}

		String menuTarget = event.getMenuTarget();

		if (menuTarget == null || !menuTarget.contains("->"))
		{
			return;
		}

		String natureSpellName = getNatureRuneSpellName(menuTarget);
		if (natureSpellName != null)
		{
			long now = System.currentTimeMillis();
			if (lastNatureRuneCastKey != null && lastNatureRuneCastKey.equals(natureSpellName) && now - lastNatureRuneCastTimeMs < 1000)
			{
				return;
			}

			lastNatureRuneCastKey = natureSpellName;
			lastNatureRuneCastTimeMs = now;

			int natureRuneCost = getNatureRuneCost(menuTarget);
			if (charges > 0)
			{
				lastChargeBeforeSpellCast = charges;
				ignoreNextChargeMessage = true;
				int newCharge = Math.max(0, charges - natureRuneCost);
				setCharges(newCharge);
			}
			else
			{
				refreshInfoBox();
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			warnIfUnchargedEquipped();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
		{
			if (!isUnchargedStaffEquipped())
			{
				unchargedNotified = false;
			}
			warnIfUnchargedEquipped();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BryophytaStaffHelperConfig.GROUP.equals(event.getGroup()))
		{
			refreshInfoBox();
			warnIfLow();
		}
	}

	private void setCharges(int newCharges)
	{
		int previousCharges = charges;
		charges = Math.max(0, Math.min(MAX_CHARGES, newCharges));

		if (charges > config.lowChargeWarning())
		{
			lowChargeNotified = false;
		}

		refreshInfoBox();

		if (charges <= config.lowChargeWarning())
		{
			if (previousCharges > config.lowChargeWarning() || previousCharges == -1 || !lowChargeNotified)
			{
				warnIfLow();
			}
		}
	}

	private void warnIfLow()
	{
		if (charges >= 0 && charges <= config.lowChargeWarning() && !lowChargeNotified)
		{
			notifier.notify("Bryophyta's staff is low: " + charges + " charges remaining.");
			lowChargeNotified = true;
		}
	}

	private void warnIfUnchargedEquipped()
	{
		if (!config.notifyUncharged() || unchargedNotified || !isUnchargedStaffEquipped())
		{
			return;
		}

		notifier.notify("Bryophyta's staff is uncharged.");
		unchargedNotified = true;
	}

	private boolean isStaffEquipped()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return false;
		}
		return equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx()) != null
			&& equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx()).getId() == ItemID.BRYOPHYTAS_STAFF;
	}

	private boolean isUnchargedStaffEquipped()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		return equipment != null
			&& equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx()).getId() == ItemID.BRYOPHYTAS_STAFF_UNCHARGED;
	}

	private void refreshInfoBox()
	{
		if (!config.showInfobox() || charges < 0)
		{
			removeInfoBox();
			return;
		}

		if (infoBox == null)
		{
			BufferedImage image = itemManager.getImage(ItemID.BRYOPHYTAS_STAFF);
			infoBox = new BryophytaStaffInfoBox(image, this);
			infoBoxManager.addInfoBox(infoBox);
		}
		infoBox.setCharges(charges, savedRunes);
	}

	private void removeInfoBox()
	{
		if (infoBox != null)
		{
			infoBoxManager.removeInfoBox(infoBox);
			infoBox = null;
		}
	}

	private static class BryophytaStaffInfoBox extends InfoBox
	{
		private int charges;
		private int savedRunes;

		BryophytaStaffInfoBox(BufferedImage image, Plugin plugin)
		{
			super(image, plugin);
		}

		void setCharges(int charges, int savedRunes)
		{
			this.charges = charges;
			this.savedRunes = savedRunes;
		}

		@Override
		public String getText()
		{
			return Integer.toString(charges);
		}

		@Override
		public Color getTextColor()
		{
			return charges == 0 ? Color.RED : Color.WHITE;
		}

		@Override
		public String getTooltip()
		{
			return "Bryophyta's staff: " + charges + " charges remaining"
				+ "<br>Nature runes saved this session: " + savedRunes;
		}
	}
}
